 h,w=len(grid),len(grid[0]); bg=Counter(x for row in grid for x in row).most_common(1)[0][0]
 out=[[bg]*w for _ in range(h)]; seen=set()
 for r in range(h):
  for c in range(w):
   col=grid[r][c]
   if col==bg or (r,c) in seen: continue
   q=[(r,c)]; seen.add((r,c)); comp=[]
   while q:
    y,x=q.pop(); comp.append((y,x))
    for yy,xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
